#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/text/localizable/localizable_property.hpp"
#include "gui_forms/control/shared_capabilities/shared_capabilities.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// TabPage's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/tab_page.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The tab's image in the TabControl's image list, by key (Windows Forms' ImageKey). A write clears image_index, as in Windows Forms; an empty key shows no image, and so does a key the list does not have. A key that is not valid UTF-8 or is longer than 256 bytes throws std::invalid_argument.
template <typename Declaring>
struct TabPageImageKeyCapability {
    PropertyView<std::string, TabPageImageKeyCapability<Declaring>> image_key;

    static void assign(TabPageImageKeyCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.image_key), std::move(incoming));
    }

    static std::string read(const TabPageImageKeyCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::string current = control.read_view(capability.image_key);
        return current;
    }
};

// The tab's image in the TabControl's image list, by index (Windows Forms' ImageIndex). A write clears image_key; -1 (the default) shows no image, and so does an index the list does not have. An index below -1 throws std::out_of_range.
template <typename Declaring>
struct TabPageImageIndexCapability {
    PropertyView<int, TabPageImageIndexCapability<Declaring>> image_index;

    static void assign(TabPageImageIndexCapability& capability, int incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.image_index), std::move(incoming));
    }

    static int read(const TabPageImageIndexCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        int current = control.read_view(capability.image_index);
        return current;
    }
};

// Every TabPage capability, in the order the declaring class takes them.
template <typename Declaring>
struct TabPageCapabilities : public TextCapability<Declaring>,
                             public TabPageImageKeyCapability<Declaring>,
                             public TabPageImageIndexCapability<Declaring> {};

} // namespace gui_forms
